job.command:
stardev
cp data_to_jet/* . cp shared/* . cp underlying_event/* . cp jet_calibration/ApplyCorrections_em_only.cpp . cp asymmetry/AnConfig.h asymmetry/AnHistograms.cpp . cp asymmetry/jes/{{CALIB_NAME}} calib.json cp -r data_to_jet/hcal_gain_corrections .
@ rline = ${JOBINDEX} + 1 set RANGE = `sed -n "${rline}p" {{RANGEFILE}}` @ line_start = $RANGE[1] @ mycount = $RANGE[2] @ line_end = ${line_start} + ${mycount} - 1 sed -n "${line_start},${line_end}p" {{LISTFILE}} > my_lines.list set RUN = `head -1 my_lines.list | grep -oE '_[0-9]{8}_(raw_)?[0-9]{7}\.MuDst' | cut -c2-9` set TAG = ${RUN}_${JOBINDEX} set TIMING = timing_${TAG}.txt
echo "========================================" echo "JOBINDEX = ${JOBINDEX}, run ${RUN}, lines ${line_start}-${line_end} (${mycount} files)" echo "========================================"
echo "# stage file catalog_events input_kB wall_s user_s sys_s maxrss_kB scratch_kB" > ${TIMING} echo "# node `hostname` cpu `grep -m1 'model name' /proc/cpuinfo | cut -d: -f2 | tr -s ' ' '_'`" >> ${TIMING}
# Compile in a subshell with the fastjet/ROOT modules, so this shell keeps # the STAR (stardev) environment root4star needs: a module purge here # cannot be undone (stardev fails after it). The programs then run # with the modules' library path (MOD_LD). /usr/bin/time -f "%e %U %S %M" -o stage.time tcsh -c 'module purge; module load fastjet-3.3.4; module load root-5.34.38; printenv LD_LIBRARY_PATH >! modules_ld.txt; g++ -m64 -O2 RecoJets.cpp VectorDict.cxx -o RecoJets `root-config --cflags --libs` `fastjet-config --cxxflags --libs` -std=c++11 && g++ -m64 -O2 UnderlyingEvent.cpp VectorDict.cxx -o UnderlyingEvent `root-config --cflags --libs` -std=c++11 && g++ -m64 -O2 ApplyCorrections_em_only.cpp VectorDict.cxx -o ApplyCorrections_em_only `root-config --cflags --libs` -std=c++11 && g++ -m64 -O2 AnHistograms.cpp VectorDict.cxx -o AnHistograms `root-config --cflags --libs` `fastjet-config --cxxflags --libs` -std=c++11' set COMPILESTATUS = $status echo "compile all 0 0 `tail -1 stage.time` 0" >> ${TIMING} if ( ${COMPILESTATUS} != 0 || ! -x RecoJets || ! -x UnderlyingEvent || ! -x ApplyCorrections_em_only || ! -x AnHistograms ) then echo "ERROR: compilation failed" exit 1 endif set MOD_LD = `cat modules_ld.txt`
set xrdname = "root://xrdstar.rcf.bnl.gov:1095" set xrdnchar = `echo $xrdname | awk '{print length($0)}'` rm -f simpletree_files.list ue_pairs.list jet_files.list touch simpletree_files.list jet_files.list set nonomatch
set i = 1 while ( ${i} <= ${mycount} ) set RAWLINE = `sed -n "${i}p" my_lines.list` set FILEURL = `echo ${RAWLINE} | rev | cut -d'/' -f2- | rev` set NEVCAT = `echo ${RAWLINE} | rev | cut -d'/' -f1 | rev` set LOCALFILE = `basename ${FILEURL}` set urlprefix = `echo ${FILEURL} | awk -v l="$xrdnchar" '{print substr($0,0,l)}'`
if ( "$xrdname" == "$urlprefix" ) then # a stalled xrootd transfer (a normal one takes seconds) is cut off # after 3 min and tried once more; a second failure skips the file /usr/bin/time -f "%e %U %S %M" -o stage.time timeout 180 xrdcp --retry 3 -s ${FILEURL} ${LOCALFILE} set FETCHSTATUS = $status if ( ${FETCHSTATUS} != 0 ) then echo "fetchretry ${LOCALFILE} ${NEVCAT} 0 `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING} rm -f ${LOCALFILE} /usr/bin/time -f "%e %U %S %M" -o stage.time timeout 180 xrdcp --retry 3 -s ${FILEURL} ${LOCALFILE} set FETCHSTATUS = $status endif else /usr/bin/time -f "%e %U %S %M" -o stage.time cp ${FILEURL} ${LOCALFILE} set FETCHSTATUS = $status endif # a timed-out transfer can leave a partial file: any non-zero status is a failure if ( ${FETCHSTATUS} != 0 || ! -f ${LOCALFILE} || -z ${LOCALFILE} ) then echo "ERROR: could not obtain ${FILEURL} (status ${FETCHSTATUS}), skipping" echo "fetchfail ${LOCALFILE} ${NEVCAT} 0 `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING} rm -f ${LOCALFILE} @ i++ continue endif set INKB = `du -k ${LOCALFILE} | cut -f1` echo "fetch ${LOCALFILE} ${NEVCAT} ${INKB} `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING}
set NBEFORE = `ls SimpleTree_mudst_*.root | grep -c '\.root$'` /usr/bin/time -f "%e %U %S %M" -o stage.time root4star -b -q runMudst.C\(\"${LOCALFILE}\",-1,-2,\".\",1,0,\"{{TRIGGER_FILTER}}\"\) >&! mudst.log echo "mudst ${LOCALFILE} ${NEVCAT} ${INKB} `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING} rm -f ${LOCALFILE} set NAFTER = `ls SimpleTree_mudst_*.root | grep -c '\.root$'` if ( ${NAFTER} <= ${NBEFORE} ) then echo "ERROR: runMudst.C produced no new SimpleTree for ${FILEURL}, skipping" tail -20 mudst.log @ i++ continue endif set STFILE = `ls -t SimpleTree_mudst_*.root | head -1` echo ${STFILE} >> simpletree_files.list
# jet finding and the UE (in-event, each file independent) on this # SimpleTree now, then delete it: scratch holds one MuDst or one # SimpleTree at a time, plus the small jet files set SUFFIX = `echo ${STFILE} | sed -e 's/^SimpleTree_mudst_//' -e 's/\.root$//'` echo "${STFILE}" >! single_file.list set INKB = `du -k ${STFILE} | cut -f1` /usr/bin/time -f "%e %U %S %M" -o stage.time env LD_LIBRARY_PATH="${MOD_LD}" ./RecoJets single_file.list "{{TRIGGER_FILTER}}" 1 1 >&! recojets.log set JETSTATUS = $status echo "jets ${STFILE} 0 ${INKB} `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING} if ( ${JETSTATUS} != 0 || ! -f jet_output.root ) then echo "ERROR: RecoJets failed on ${STFILE}, skipping" tail -20 recojets.log rm -f ${STFILE} jet_output.root @ i++ continue endif mv jet_output.root jet_output_${SUFFIX}.root echo "jet_output_${SUFFIX}.root ${STFILE}" >! ue_pairs.list /usr/bin/time -f "%e %U %S %M" -o stage.time env LD_LIBRARY_PATH="${MOD_LD}" ./UnderlyingEvent ue_pairs.list >&! ue.log set UESTATUS = $status echo "ue ${STFILE} 0 ${INKB} `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING} rm -f ${STFILE} if ( ${UESTATUS} != 0 ) then echo "ERROR: UnderlyingEvent failed on ${STFILE}, skipping" tail -20 ue.log rm -f jet_output_${SUFFIX}.root @ i++ continue endif echo "jet_output_${SUFFIX}.root" >> jet_files.list @ i++ end
set NPRODUCED = `wc -l < jet_files.list` echo "Produced ${NPRODUCED}/${mycount} jet files (`wc -l < simpletree_files.list` SimpleTrees)" if ( ${NPRODUCED} == 0 ) then echo "ERROR: no jet files produced" exit 1 endif
# JES calibration of the UE-subtracted energy, in place /usr/bin/time -f "%e %U %S %M" -o stage.time env LD_LIBRARY_PATH="${MOD_LD}" ./ApplyCorrections_em_only jet_files.list calib.json echo "calib all ${NPRODUCED} 0 `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING}
# A_N yield histograms /usr/bin/time -f "%e %U %S %M" -o stage.time env LD_LIBRARY_PATH="${MOD_LD}" ./AnHistograms jet_files.list an_hists_${TAG}.root echo "hists all ${NPRODUCED} 0 `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING} echo "output an_hists_${TAG}.root 0 `du -k an_hists_${TAG}.root | cut -f1` 0 0 0 0 0" >> ${TIMING} echo "jetfiles all 0 `cat jet_files.list | xargs du -ck | tail -1 | cut -f1` 0 0 0 0 0" >> ${TIMING}
# calibrated jet files: kept for every {{KEEP_JETS}}-th job (0 = none), else deleted set KEEPJ = 0 if ( {{KEEP_JETS}} > 0 ) then @ jmod = ${JOBINDEX} % {{KEEP_JETS}} if ( ${jmod} == 0 ) set KEEPJ = 1 endif if ( ${KEEPJ} == 1 ) then # one merged file per job (a directory of ~4,400 files, not ~176,000) /usr/bin/time -f "%e %U %S %M" -o stage.time tcsh -c 'module purge; module load fastjet-3.3.4; module load root-5.34.38; hadd -f jets_'${TAG}'.root `cat jet_files.list`' >&! hadd.log set HADDSTATUS = $status echo "merge all ${NPRODUCED} 0 `tail -1 stage.time` `du -sk . | cut -f1`" >> ${TIMING} if ( ${HADDSTATUS} != 0 || ! -f jets_${TAG}.root ) then echo "ERROR: hadd of the jet files failed; jets not kept" tail -20 hadd.log rm -f jets_${TAG}.root endif endif foreach f ( `cat jet_files.list` ) rm -f ${f} end rm -f my_lines.list simpletree_files.list single_file.list ue_pairs.list jet_files.list stage.time modules_ld.txt cat ${TIMING}
